-- Lab analyte catalogue and aliases (J12.5; docs/architecture/analyte-catalog.md).
-- Generated by `go run ./internal/documents/analytes/gen`; do not edit. Codes added later get their own migration.

-- +goose Up
CREATE TABLE analytes (
  id             smallint PRIMARY KEY,
  code           text NOT NULL UNIQUE CHECK (code ~ '^[a-z][a-z0-9_]*$'),
  name           text NOT NULL,
  canonical_unit text,
  loinc          text CHECK (loinc ~ '^[0-9]{1,7}-[0-9]$')
);
COMMENT ON TABLE analytes IS 'Lab analytes owned by internal/documents/analytes. No reference ranges: ranges come from the printed report.';
COMMENT ON COLUMN analytes.canonical_unit IS 'Null when values are kept as printed only. Conversions are owned by code.';
COMMENT ON COLUMN analytes.loinc IS 'Only from a verified loinc.org lookup, never guessed.';
REVOKE INSERT, UPDATE, DELETE ON analytes FROM vitamux_app;

CREATE TABLE analyte_aliases (
  id         bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  analyte_id smallint NOT NULL REFERENCES analytes,
  label      text NOT NULL CHECK (label <> ''),
  label_key  text NOT NULL CHECK (label_key <> ''),
  user_id    uuid REFERENCES users ON DELETE CASCADE,
  created_by text,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK ((user_id IS NULL) = (created_by IS NULL))
);
COMMENT ON TABLE analyte_aliases IS 'Printed labels mapped to analytes: seeded rows (user_id null, read-only by convention) and owner aliases, which take precedence.';
COMMENT ON COLUMN analyte_aliases.label_key IS 'analytes.LabelKey(label): lower case, punctuation runs collapsed to one space.';
CREATE UNIQUE INDEX analyte_aliases_seed_idx ON analyte_aliases (label_key) WHERE user_id IS NULL;
CREATE UNIQUE INDEX analyte_aliases_owner_idx ON analyte_aliases (user_id, label_key) WHERE user_id IS NOT NULL;
REVOKE UPDATE ON analyte_aliases FROM vitamux_app;

ALTER TABLE lab_extracted_rows ADD CONSTRAINT lab_extracted_rows_suggested_analyte_id_fkey
  FOREIGN KEY (suggested_analyte_id) REFERENCES analytes;
ALTER TABLE lab_results ADD CONSTRAINT lab_results_analyte_id_fkey FOREIGN KEY (analyte_id) REFERENCES analytes;



-- +goose Down
ALTER TABLE lab_results DROP CONSTRAINT lab_results_analyte_id_fkey;
ALTER TABLE lab_extracted_rows DROP CONSTRAINT lab_extracted_rows_suggested_analyte_id_fkey;
DROP TABLE analyte_aliases, analytes;
